+  }
+  return { ok: false, why: `"${String((m as { kind?: unknown }).kind)}" is not a kind of message` };
+}
+
+// ── WHAT THIS DEVICE KNOWS ABOUT THE OTHER ONE ──────────────────────────────────────────────────────
+export interface LinkState {
