+export const initLink = (me: Seat, code: string): LinkState => ({
+  me, code, theirFlight: null, theirGimbal: null, theirName: "",
+  lastHeardMs: 0, seenSeq: { pilot: -1, targeteer: -1 }, accepted: 0, refused: 0, lastRefusal: "",
+});
