+  if (m.seat === s.me) return s;                                   // our own words, come back around
+  if (m.seq <= s.seenSeq[m.seat]) return s;                        // already had this one, on another path
+  const next: LinkState = {
+    ...s,
+    seenSeq: { ...s.seenSeq, [m.seat]: m.seq },
+    lastHeardMs: nowMs,
+    accepted: s.accepted + 1,
+  };
