+  const p = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
+  const code = (p.get("crew") || "").trim().toUpperCase();
+  const seat = p.get("seat");
+  if (!code) return null;
+  if (seat !== "pilot" && seat !== "targeteer") return null;
+  return { code, seat };
+}
