+        method: "POST", headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({ crew: s.code, msg: m }), keepalive: true,
+      }).catch(() => { /* the other two may still have carried it */ });
+      return s;
+    });
+  }, []);
+
+  return { state, say, paths };
+}
